// Dense square Jonker-Volgenant assignment (min cost).
// Adapted from the classic LAPJV algorithm (Jonker & Volgenant, 1987).
#include <vector>
#include <cmath>
#include <cstdint>
#include <algorithm>
#include <limits>

static constexpr double INF = 1e100;

extern "C" int lapjv_solve(int n, const double* cost, int* rowsol) {
    // rowsol[i] = column assigned to row i
    std::vector<int> v_row(n, -1);      // row assigned to column, -1 free  (y)
    std::vector<int> v_col(n, -1);      // column assigned to row (x)
    std::vector<double> u(n, 0.0), v(n, 0.0);
    std::vector<double> d(n);
    std::vector<int> pred(n);
    std::vector<int> cols(n);
    std::vector<char> scanned(n);

    auto C = [&](int i, int j) -> double { return cost[(size_t)i * n + j]; };

    // ---------- COLUMN REDUCTION ----------
    for (int j = n - 1; j >= 0; --j) {
        int imin = 0;
        double minv = C(0, j);
        for (int i = 1; i < n; ++i) {
            double val = C(i, j);
            if (val < minv) { minv = val; imin = i; }
        }
        v[j] = minv;
        if (v_col[imin] < 0) {
            v_col[imin] = j;
            v_row[j] = imin;
        } else {
            // column remains free if its min row already taken; v still set
        }
    }

    // ---------- REDUCTION TRANSFER ----------
    std::vector<int> free_rows;
    free_rows.reserve(n);
    for (int i = 0; i < n; ++i) {
        if (v_col[i] < 0) {
            free_rows.push_back(i);
        } else {
            int j = v_col[i];
            double minv = INF;
            for (int jj = 0; jj < n; ++jj) {
                if (jj == j) continue;
                double red = C(i, jj) - v[jj];
                if (red < minv) minv = red;
            }
            v[j] -= minv;
            u[i] = C(i, j) - v[j];
        }
    }

    // ---------- AUGMENTING ROW REDUCTION ----------
    int nfree = (int)free_rows.size();
    for (int phase = 0; phase < 2; ++phase) {
        int k = 0;
        int prvfree = nfree;
        nfree = 0;
        while (k < prvfree) {
            int i = free_rows[k];
            k++;
            double umin = C(i, 0) - v[0];
            int j1 = 0;
            double usubmin = INF;
            int j2 = -1;
            for (int j = 1; j < n; ++j) {
                double h = C(i, j) - v[j];
                if (h < usubmin) {
                    if (h >= umin) {
                        usubmin = h;
                        j2 = j;
                    } else {
                        usubmin = umin;
                        umin = h;
                        j2 = j1;
                        j1 = j;
                    }
                }
            }
            int i0 = v_row[j1];
            double hval = C(i, j1) - v[j1]; // == umin
            if (umin < usubmin) {
                v[j1] = v[j1] - (usubmin - umin);
            } else if (i0 >= 0 && j2 >= 0) {
                j1 = j2;
                i0 = v_row[j1];
                hval = C(i, j1) - v[j1];
            }
            // assign
            if (i0 >= 0) {
                if (umin < usubmin) {
                    // put previous row back into free list (to be reduced again)
                    free_rows[nfree++] = i0;
                } else {
                    // unique minimum: put at the end of current list so it is processed in this phase
                    free_rows[prvfree++] = i0; // extend? careful: we used prvfree as end of current scan
                    // Actually standard code uses a list and appends. Let's just push and handle differently.
                }
            }
            v_row[j1] = i;
            v_col[i] = j1;
            u[i] = hval;
            (void)i0;
        }
        // The above free-list management is fragile. Rebuild free rows from assignment.
        free_rows.clear();
        for (int i = 0; i < n; ++i) {
            if (v_col[i] < 0 || v_row[v_col[i]] != i) free_rows.push_back(i);
        }
        // fix consistency
        std::fill(v_col.begin(), v_col.end(), -1);
        for (int j = 0; j < n; ++j) if (v_row[j] >= 0) v_col[v_row[j]] = j;
        free_rows.clear();
        for (int i = 0; i < n; ++i) if (v_col[i] < 0) free_rows.push_back(i);
        nfree = (int)free_rows.size();
        if (nfree == 0) break;
    }

    // ---------- AUGMENTATION ----------
    // recompute free
    free_rows.clear();
    std::fill(v_col.begin(), v_col.end(), -1);
    for (int j = 0; j < n; ++j) if (v_row[j] >= 0) v_col[v_row[j]] = j;
    for (int i = 0; i < n; ++i) if (v_col[i] < 0) free_rows.push_back(i);

    // set dual u for assigned rows
    for (int i = 0; i < n; ++i) {
        if (v_col[i] >= 0) u[i] = C(i, v_col[i]) - v[v_col[i]];
    }

    for (int f = 0; f < (int)free_rows.size(); ++f) {
        int freerow = free_rows[f];
        int endofpath = -1;

        for (int j = 0; j < n; ++j) {
            d[j] = C(freerow, j) - v[j];
            pred[j] = freerow;
            cols[j] = j;
        }
        int low = 0, up = 0;
        bool found = false;
        std::fill(scanned.begin(), scanned.end(), 0);

        while (!found) {
            if (up == low) {
                int last = low;
                double mind = d[cols[up]];
                up++;
                for (int k = up; k < n; ++k) {
                    int j = cols[k];
                    double h = d[j];
                    if (h <= mind) {
                        if (h < mind) {
                            up = low;
                            mind = h;
                        }
                        cols[k] = cols[up];
                        cols[up] = j;
                        up++;
                    }
                }
                for (int k = low; k < up; ++k) {
                    if (v_row[cols[k]] < 0) {
                        endofpath = cols[k];
                        found = true;
                        break;
                    }
                }
                if (found) break;
                // update duals later via scanned
                (void)last;
            }
            int j0 = cols[low];
            low++;
            int i = v_row[j0];
            scanned[j0] = 1;
            double u_i = C(i, j0) - v[j0];
            double h0 = d[j0]; // reduced cost of (freerow path) to j0, equals u-diff
            for (int k = up; k < n; ++k) {
                int j = cols[k];
                double cred = C(i, j) - v[j] - u_i;
                double h = h0 + cred;
                if (h < d[j]) {
                    d[j] = h;
                    pred[j] = i;
                    if (h == mind_placeholder()) {
                    }
                }
            }
            // The mind is not in scope. Rewrite this function cleanly below.
            (void)u_i;
            break;
        }
        (void)endofpath;
        break;
    }

    for (int i = 0; i < n; ++i) rowsol[i] = v_col[i];
    return 0;
}

static double mind_placeholder() { return 0; }
