// Dense minimum-cost assignment, Jonker-Volgenant (1987).
// cost: row-major n*n float64. rowsol[i] = assigned column.
#include <vector>
#include <cstdint>
#include <algorithm>
#include <cstring>

static constexpr double BIG = 1e18;

extern "C" int lapjv_solve(int n, const double* cost, int* rowsol) {
    const int N = n;
    std::vector<int> x(N, -1);          // column of row
    std::vector<int> y(N, -1);          // row of column
    std::vector<double> u(N, 0.0);      // dual row
    std::vector<double> v(N, 0.0);      // dual col
    std::vector<double> d(N);
    std::vector<int> pred(N);
    std::vector<int> col(N);
    std::vector<int> free(N);
    std::vector<char> unique(N, 0);

    auto C = [&](int i, int j) -> double {
        return cost[(size_t)i * N + j];
    };

    // ---- column reduction ----
    for (int j = N - 1; j >= 0; --j) {
        double minv = C(0, j);
        int imin = 0;
        for (int i = 1; i < N; ++i) {
            double val = C(i, j);
            if (val < minv) { minv = val; imin = i; }
        }
        v[j] = minv;
        if (x[imin] == -1) {
            x[imin] = j;
            y[j] = imin;
        } else {
            unique[imin] = 0; // not unique anymore conceptually
        }
    }

    // ---- reduction transfer ----
    int nfree = 0;
    for (int i = 0; i < N; ++i) {
        if (x[i] == -1) {
            free[nfree++] = i;
        } else {
            int j1 = x[i];
            double minv = BIG;
            for (int j = 0; j < N; ++j) {
                if (j == j1) continue;
                double red = C(i, j) - v[j];
                if (red < minv) minv = red;
            }
            v[j1] -= minv;
        }
    }

    // ---- augmenting row reduction ----
    for (int phase = 0; phase < 2; ++phase) {
        int k = 0;
        int prv_nfree = nfree;
        nfree = 0;
        while (k < prv_nfree) {
            int i = free[k++];
            double umin = C(i, 0) - v[0];
            int j1 = 0;
            double usub = BIG;
            int j2 = 0;
            for (int j = 1; j < N; ++j) {
                double h = C(i, j) - v[j];
                if (h < usub) {
                    if (h >= umin) {
                        usub = h;
                        j2 = j;
                    } else {
                        usub = umin;
                        umin = h;
                        j2 = j1;
                        j1 = j;
                    }
                }
            }
            int i0 = y[j1];
            if (umin < usub) {
                v[j1] -= (usub - umin);
            } else if (i0 >= 0) {
                j1 = j2;
                i0 = y[j1];
            }
            x[i] = j1;
            y[j1] = i;
            if (i0 >= 0) {
                if (umin < usub) {
                    free[nfree++] = i0;          // new free, next phase
                    x[i0] = -1;
                } else {
                    free[prv_nfree++] = i0;      // process again this phase
                    x[i0] = -1;
                }
            }
        }
        if (nfree == 0) break;
    }

    // rebuild consistent assignment from y (columns)
    std::fill(x.begin(), x.end(), -1);
    for (int j = 0; j < N; ++j) {
        if (y[j] >= 0) x[y[j]] = j;
    }
    nfree = 0;
    for (int i = 0; i < N; ++i) {
        if (x[i] < 0) free[nfree++] = i;
        else u[i] = C(i, x[i]) - v[x[i]];
    }

    // ---- augmentation ----
    for (int f = 0; f < nfree; ++f) {
        int freerow = free[f];
        int endofpath = -1;

        for (int j = 0; j < N; ++j) {
            d[j] = C(freerow, j) - v[j];
            pred[j] = freerow;
            col[j] = j;
        }

        int low = 0;
        int up = 0;
        bool found = false;
        double mind = 0.0;

        while (!found) {
            if (up == low) {
                mind = d[col[up]];
                int last = low;
                ++up;
                for (int k = up; k < N; ++k) {
                    int j = col[k];
                    double h = d[j];
                    if (h <= mind) {
                        if (h < mind) {
                            up = low;
                            mind = h;
                        }
                        col[k] = col[up];
                        col[up] = j;
                        ++up;
                    }
                }
                for (int k = low; k < up; ++k) {
                    if (y[col[k]] < 0) {
                        endofpath = col[k];
                        found = true;
                        break;
                    }
                }
                (void)last;
            }
            if (found) break;

            int j1 = col[low];
            ++low;
            int i = y[j1];
            double u_i = C(i, j1) - v[j1];
            for (int k = up; k < N; ++k) {
                int j = col[k];
                double h = C(i, j) - v[j] - u_i + mind; // d[j1] == mind for cols in [low-1, up)
                // d[j1] equals mind because j1 was among the minimum set
                if (h < d[j]) {
                    d[j] = h;
                    pred[j] = i;
                    if (h == mind) {
                        if (y[j] < 0) {
                            endofpath = j;
                            found = true;
                            break;
                        } else {
                            col[k] = col[up];
                            col[up] = j;
                            ++up;
                        }
                    }
                }
            }
        }

        // update dual variables
        for (int k = 0; k < low; ++k) {
            int j1 = col[k];
            v[j1] += d[j1] - mind;
            int i = y[j1];
            u[i] = C(i, j1) - v[j1];
        }
        // augment along path
        int j = endofpath;
        while (true) {
            int i = pred[j];
            y[j] = i;
            int jnext = x[i];
            x[i] = j;
            j = jnext;
            if (i == freerow) break;
        }
    }

    for (int i = 0; i < N; ++i) rowsol[i] = x[i];
    return 0;
}
