            int j1 = col[low++]; int i = y[j1];
            double u_i = C(i, j1) - v[j1];
            ++aug_scans;
            for (int k = up; k < N; ++k) {
                int j = col[k];
                double h = C(i, j) - v[j] - u_i + mind;
                if (h < d[j]) {
                    d[j] = h; pred[j] = i;
                    if (h == mind) {
                        if (y[j] < 0) { endofpath = j; found = true; break; }
                        else { col[k] = col[up]; col[up] = j; ++up; }
                    }
                }
            }
        }
        for (int k = 0; k < low; ++k) {
            int j1 = col[k]; v[j1] += d[j1] - mind;
        }
        int j = endofpath;
        while (true) {
            int i = pred[j]; y[j] = i; int jnext = x[i]; x[i] = j; j = jnext;
            if (i == freerow) break;
        }
    }
    auto tE = clk::now();
    auto ms = [](auto a, auto b){ return std::chrono::duration<double, std::milli>(b-a).count(); };
    std::fprintf(stderr, "nfree_final_augs=%d scans=%d colred=%.2f redtrans=%.2f rowred=%.2f aug=%.2f total=%.2f\n",
        nfree, aug_scans, ms(tA,tB), ms(tB,tC), ms(tC,tD), ms(tD,tE), ms(t0,tE));
    for (int i = 0; i < N; ++i) rowsol[i] = x[i];
    return 0;
}
