// Sparse-capable JV: we still store dense cost but skip edges above a threshold
// by using a CSR of candidate edges. For correctness we can fall back.
// This version: auction algorithm (Bertsekas) on dense matrix, epsilon-scaling.
#include <vector>
#include <cstdint>
#include <algorithm>
#include <cmath>
#include <cstring>

// Returns 0 on success. rowsol[i] = column.
extern "C" int auction_solve(int n, const double* cost, int* rowsol, double eps_final) {
    const int N = n;
    // We maximize -cost, i.e. benefits b_ij = -cost_ij
    // prices p_j, bids
    std::vector<double> price(N, 0.0);
    std::vector<int> owner(N, -1);     // row owning column
    std::vector<int> assign(N, -1);    // column of row
    std::vector<char> unassigned(N, 1);

    // epsilon scaling
    // estimate cost scale
    double cmax = 0.0;
    for (int i = 0; i < N; ++i) {
        const double* row = cost + (size_t)i * N;
        for (int j = 0; j < N; ++j) cmax = std::max(cmax, row[j]);
    }
    double eps = cmax / 2.0 + 1.0;
    if (eps_final <= 0) eps_final = 1e-9;

    std::vector<int> free_list(N);
    std::vector<double> best_val(N);
    std::vector<int> best_j(N);

    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        int nfree = N;
        for (int i = 0; i < N; ++i) free_list[i] = i;

        int guard = 0;
        const int GUARD_MAX = N * 40;
        while (nfree > 0 && guard < GUARD_MAX) {
            ++guard;
            // each free row bids for its best object
            // process one at a time (Gauss-Seidel) for faster convergence
            int i = free_list[--nfree];
            const double* row = cost + (size_t)i * N;
            // find best and second best benefit = -cost - price
            double v1 = -row[0] - price[0];
            int j1 = 0;
            double v2 = -1e300;
            for (int j = 1; j < N; ++j) {
                double val = -row[j] - price[j];
                if (val > v1) { v2 = v1; v1 = val; j1 = j; }
                else if (val > v2) v2 = val;
            }
            // bid: raise price so that best is eps better than second
            // new price = price + (v1 - v2) + eps, but benefit uses -cost
            // price_j increases by (benefit1 - benefit2) + eps
            double bid_inc = (v1 - v2) + eps;
            price[j1] += bid_inc;
            int prev = owner[j1];
            owner[j1] = i;
            assign[i] = j1;
            if (prev >= 0) {
                assign[prev] = -1;
                free_list[nfree++] = prev;
            }
        }
        if (nfree == 0) {
            if (eps <= eps_final) {
                for (int i = 0; i < N; ++i) rowsol[i] = assign[i];
                return 0;
            }
            eps *= 0.25;
            if (eps < eps_final) eps = eps_final;
            // keep prices as warm start
        } else {
            // failed to assign at this eps, reduce eps and retry from scratch prices? keep prices
            eps *= 0.25;
            if (eps < eps_final) {
                // give up
                for (int i = 0; i < N; ++i) rowsol[i] = assign[i];
                return 1;
            }
        }
    }
}
