// Auction on K-nearest candidates per row, with a dense fallback scan if needed.
#include <vector>
#include <cstdint>
#include <algorithm>
#include <cmath>
#include <cstring>
#include <cstdio>

extern "C" int auction_k(int n, const double* cost, int* rowsol, int K, double eps_final) {
    const int N = n;
    if (K > N) K = N;
    if (K < 2) K = 2;

    // Build K nearest columns per row (partial selection)
    std::vector<int> cand((size_t)N * K);
    std::vector<double> cand_cost((size_t)N * K);
    std::vector<int> idx(N);
    for (int i = 0; i < N; ++i) {
        const double* row = cost + (size_t)i * N;
        for (int j = 0; j < N; ++j) idx[j] = j;
        std::nth_element(idx.begin(), idx.begin() + K, idx.end(), [&](int a, int b){ return row[a] < row[b]; });
        // sort the K for stable second-best
        std::sort(idx.begin(), idx.begin() + K, [&](int a, int b){ return row[a] < row[b]; });
        for (int k = 0; k < K; ++k) {
            cand[(size_t)i * K + k] = idx[k];
            cand_cost[(size_t)i * K + k] = row[idx[k]];
        }
    }

    double cmax = 0;
    for (double x : cand_cost) cmax = std::max(cmax, x);
    double eps = std::max(cmax / 4.0, 1e-3);

    std::vector<double> price(N, 0.0);
    std::vector<int> owner(N, -1);
    std::vector<int> assign(N, -1);
    std::vector<int> free_list(N);

    int rounds = 0;
    while (rounds < 30) {
        ++rounds;
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        int nfree = N;
        for (int i = 0; i < N; ++i) free_list[i] = i;
        int guard = 0;
        const int GUARD_MAX = N * 80;
        bool stuck = false;
        while (nfree > 0 && guard < GUARD_MAX) {
            ++guard;
            int i = free_list[--nfree];
            const int* cj = cand.data() + (size_t)i * K;
            const double* cc = cand_cost.data() + (size_t)i * K;
            double v1 = -1e300, v2 = -1e300;
            int j1 = cj[0];
            for (int k = 0; k < K; ++k) {
                double val = -cc[k] - price[cj[k]];
                if (val > v1) { v2 = v1; v1 = val; j1 = cj[k]; }
                else if (val > v2) v2 = val;
            }
            if (v2 < -1e299) v2 = v1 - 1.0; // only one
            double bid_inc = (v1 - v2) + eps;
            price[j1] += bid_inc;
            int prev = owner[j1];
            owner[j1] = i;
            assign[i] = j1;
            if (prev >= 0) {
                assign[prev] = -1;
                free_list[nfree++] = prev;
            }
        }
        if (nfree == 0) {
            if (eps <= eps_final) {
                for (int i = 0; i < N; ++i) rowsol[i] = assign[i];
                return 0;
            }
            eps *= 0.2;
            if (eps < eps_final) eps = eps_final;
        } else {
            eps *= 0.2;
            if (eps < eps_final * 0.5) {
                for (int i = 0; i < N; ++i) rowsol[i] = assign[i];
                return 1;
            }
        }
    }
    for (int i = 0; i < N; ++i) rowsol[i] = assign[i];
    return 2;
}
