// Cost-scaling push-relabel for the assignment problem (Goldberg-Kennedy style),
// adapted from the classic CSA description. Dense cost matrix, min-cost perfect matching
// on a complete bipartite graph.
//
// This is a relatively direct implementation of the "cost scaling" algorithm
// with push/relabel and admissible graph, plus global price updates via Dijkstra
// when progress stalls. Aimed at n=600.
#include <vector>
#include <cstdint>
#include <algorithm>
#include <cmath>
#include <cstring>
#include <queue>
#include <cstdio>
#include <limits>

extern "C" int cs_assign(int n, const double* cost, int* rowsol) {
    const int N = n;
    const int SRC = 2 * N;
    const int SNK = 2 * N + 1;
    const int V = 2 * N + 2;
    // Nodes: 0..N-1 rows, N..2N-1 cols
    // We'll use double costs scaled to int64.
    // Scale so that 1 unit is well below 1e-9 relative.
    double maxc = 0;
    for (size_t i = 0; i < (size_t)N * N; ++i) maxc = std::max(maxc, cost[i]);
    // integer cost = round(cost * SCALE)
    const double SCALE = 1e7; // 1e-7 absolute, checker tol is 1e-7 on plan not cost. Need exact plan.
    // 1e7 may not be enough to distinguish. Use 1e9.
    const double SCALE2 = 1e9;
    (void)SCALE;

    auto IC = [&](int i, int j) -> int64_t {
        return (int64_t)std::llround(cost[(size_t)i * N + j] * SCALE2);
    };

    // prices (potentials) on all nodes, int64
    std::vector<int64_t> pot(V, 0);
    // residual: each row has flow 0/1 to each col. Store matching: match_row[i] = col or -1
    std::vector<int> match_row(N, -1);
    std::vector<int> match_col(N, -1);

    // epsilon
    int64_t eps = 1;
    {
        int64_t mx = 1;
        // sample max cost
        mx = (int64_t)std::llround(maxc * SCALE2) + 1;
        eps = 1;
        while (eps < mx) eps <<= 1;
    }

    // excess
    std::vector<int> excess(V, 0);
    // source connected to all rows with supply 1, cols connected to sink demand 1
    // Initially no flow: rows have excess +1 (from source), sink side cols need flow so we give cols excess 0 and
    // track deficit. Standard: push from source.
    // We'll implement successive shortest paths with potentials instead — simpler and for n=600 with
    // reduced costs it is Dijkstra * n. With a good potential and early column reduction it can be fast
    // if we use a radix/dial bucket. Let's do SSP with a Dial-like bucket on reduced costs... 
    // Actually for assignment, Hungarian with potentials is SSP. The slow part is dense Dijkstra.
    // Use a thresholded candidate Dijkstra: only scan K best edges, expanding K if needed.

    // --- Successive shortest paths with potentials, dense, but using a partial scan ---
    // Initialize potentials with column min (dual v)
    std::vector<int64_t> u(N, 0), v(N, 0); // row and col potentials; reduced cost IC - u - v >= 0
    for (int j = 0; j < N; ++j) {
        int64_t mn = IC(0, j);
        for (int i = 1; i < N; ++i) mn = std::min(mn, IC(i, j));
        v[j] = mn;
    }

    // We'll assign free rows one by one via Dijkstra on reduced costs.
    std::vector<int64_t> dist(N);
    std::vector<int> pred(N);
    std::vector<char> used(N);

    // binary heap Dijkstra over columns
    using P = std::pair<int64_t, int>;
    std::priority_queue<P, std::vector<P>, std::greater<P>> pq;

    for (int i = 0; i < N; ++i) {
        // Dijkstra from row i
        std::fill(dist.begin(), dist.end(), std::numeric_limits<int64_t>::max() / 4);
        std::fill(pred.begin(), pred.end(), -1);
        std::fill(used.begin(), used.end(), 0);
        while (!pq.empty()) pq.pop();
        // init: edges from free row i to all columns
        const double* row = cost + (size_t)i * N;
        for (int j = 0; j < N; ++j) {
            int64_t rc = (int64_t)std::llround(row[j] * SCALE2) - u[i] - v[j];
            dist[j] = rc;
            pred[j] = i;
            pq.emplace(rc, j);
        }
        int sink_col = -1;
        while (!pq.empty()) {
            auto [d, j] = pq.top(); pq.pop();
            if (used[j]) continue;
            if (d != dist[j]) continue;
            used[j] = 1;
            if (match_col[j] < 0) { sink_col = j; break; }
            int i2 = match_col[j];
            const double* row2 = cost + (size_t)i2 * N;
            int64_t base = (int64_t)std::llround(row2[j] * SCALE2); // matched edge
            // leaving matched edge: reduced cost of reverse is -(IC - u - v) = 0 if tight, but generally
            // dist to reach i2's other columns: dist[j] + (IC(i2,j2) - u[i2] - v[j2]) - (IC(i2,j) - u[i2] - v[j])
            int64_t matched_rc = base - u[i2] - v[j];
            for (int j2 = 0; j2 < N; ++j2) {
                if (used[j2]) continue;
                int64_t rc = (int64_t)std::llround(row2[j2] * SCALE2) - u[i2] - v[j2];
                int64_t nd = dist[j] + rc - matched_rc;
                if (nd < dist[j2]) {
                    dist[j2] = nd;
                    pred[j2] = i2;
                    pq.emplace(nd, j2);
                }
            }
        }
        if (sink_col < 0) return 1;
        // update potentials
        int64_t delta = dist[sink_col];
        for (int j = 0; j < N; ++j) if (used[j]) v[j] += dist[j] - delta;
        // u update for visited rows: u[i] += delta? standard: u decreases by dist of matched
        // We'll set u from tightness after augmenting.
        // augment
        int j = sink_col;
        while (true) {
            int i2 = pred[j];
            int jprev = match_row[i2];
            match_row[i2] = j;
            match_col[j] = i2;
            if (i2 == i) break;
            j = jprev;
        }
        // refresh u for assigned rows to keep reduced costs consistent: u[i] = IC(i, match) - v[match]
        for (int ii = 0; ii < N; ++ii) {
            if (match_row[ii] >= 0) {
                int jj = match_row[ii];
                u[ii] = (int64_t)std::llround(cost[(size_t)ii * N + jj] * SCALE2) - v[jj];
            }
        }
    }
    for (int i = 0; i < N; ++i) rowsol[i] = match_row[i];
    return 0;
}
