#include <cmath>
#include <cstring>
#include <cstdio>

// Auction on per-row candidate lists. cand_idx is n*K, cand_cost is n*K.
// If a row has fewer, pad with -1.
// Returns assignment and column prices.
extern "C" int auction_cand(
    int n, int K,
    const int* cand_idx, const double* cand_cost,
    int* rowsol, double* price_out,
    double eps_final, int max_rounds)
