import ctypes, time, numpy as np
from scipy.optimize import linear_sum_assignment
from reference import Task

lib = ctypes.CDLL("./liblapjv.so")
lib.auction_cand.argtypes = [ctypes.c_int, ctypes.c_int,
    ctypes.POINTER(ctypes.c_int), ctypes.POINTER(ctypes.c_double),
    ctypes.POINTER(ctypes.c_int), ctypes.POINTER(ctypes.c_double),
    ctypes.c_double, ctypes.c_int]
lib.auction_cand.restype = ctypes.c_int

def candidates(M, K):
    n = M.shape[0]
    idx = np.argpartition(M, K, axis=1)[:, :K]
    # sort them
    rows = np.arange(n)[:, None]
    costs = M[rows, idx]
    order = np.argsort(costs, axis=1)
    idx = idx[rows, order]
    costs = costs[rows, order]
    return np.ascontiguousarray(idx, dtype=np.int32), np.ascontiguousarray(costs, dtype=np.float64)

