#include <vector>
#include <cstdint>
#include <algorithm>
#include <cmath>
#include <cstring>
#include <cstdio>

extern "C" int auction_cand(
    int n, int K,
    const int* cand_idx, const double* cand_cost,
    int* rowsol, double* price_out,
    double eps_final, int max_rounds)
{
    const int N = n;
    std::vector<double> price(N, 0.0);
    std::vector<int> owner(N, -1);
    std::vector<int> assign(N, -1);
    std::vector<int> free_list(N);

    double cmax = 0;
    for (int i = 0; i < N * K; ++i) if (cand_idx[i] >= 0) cmax = std::max(cmax, cand_cost[i]);
    double eps = std::max(cmax / 4.0, 1e-3);

    int rounds = 0;
    while (rounds < max_rounds) {
        ++rounds;
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        int nfree = N;
        for (int i = 0; i < N; ++i) free_list[i] = i;
        int guard = 0;
        const int GUARD_MAX = N * 200;
        while (nfree > 0 && guard < GUARD_MAX) {
            ++guard;
            int i = free_list[--nfree];
            const int* cj = cand_idx + (size_t)i * K;
            const double* cc = cand_cost + (size_t)i * K;
            double v1 = -1e300, v2 = -1e300;
            int j1 = -1;
            for (int k = 0; k < K; ++k) {
                int j = cj[k];
                if (j < 0) continue;
                double val = -cc[k] - price[j];
                if (val > v1) { v2 = v1; v1 = val; j1 = j; }
                else if (val > v2) v2 = val;
            }
            if (j1 < 0) {
                for (int i2 = 0; i2 < N; ++i2) rowsol[i2] = assign[i2];
                return 3;
            }
            if (v2 < -1e200) v2 = v1 - 1.0;
            price[j1] += (v1 - v2) + eps;
            int prev = owner[j1];
            owner[j1] = i;
            assign[i] = j1;
            if (prev >= 0) {
                assign[prev] = -1;
                free_list[nfree++] = prev;
            }
        }
        if (nfree == 0) {
            if (eps <= eps_final) {
                for (int i = 0; i < N; ++i) rowsol[i] = assign[i];
                for (int j = 0; j < N; ++j) price_out[j] = price[j];
                return 0;
            }
            eps *= 0.2;
            if (eps < eps_final) eps = eps_final;
        } else {
            eps *= 0.2;
            if (eps < eps_final) {
                for (int i = 0; i < N; ++i) rowsol[i] = assign[i];
                for (int j = 0; j < N; ++j) price_out[j] = price[j];
                return 1;
            }
        }
    }
    for (int i = 0; i < N; ++i) rowsol[i] = assign[i];
    for (int j = 0; j < N; ++j) price_out[j] = price[j];
    return 2;
}

// Find edges with reduced cost M[i,j] + u[i] + price[j] < -tol
// that are not already in the candidate set. Append them into extra arrays.
// cand_idx is n*K with -1 padding. Returns number of violating edges found (capped).
extern "C" int find_violations(
    int n, const double* cost, const double* u, const double* price,
    const int* cand_idx, int K,
    int* out_i, int* out_j, int max_out, double tol)
{
    const int N = n;
    int cnt = 0;
    for (int i = 0; i < N && cnt < max_out; ++i) {
        const double* row = cost + (size_t)i * N;
        const int* cj = cand_idx + (size_t)i * K;
        double ui = u[i];
        for (int j = 0; j < N; ++j) {
            double red = row[j] + ui + price[j];
            if (red < -tol) {
                bool known = false;
                for (int k = 0; k < K; ++k) {
                    if (cj[k] == j) { known = true; break; }
                    if (cj[k] < 0) break;
                }
                if (!known) {
                    out_i[cnt] = i;
                    out_j[cnt] = j;
                    ++cnt;
                    if (cnt >= max_out) break;
                }
            }
        }
    }
    return cnt;
}
