#include <vector>
#include <cstdint>
#include <algorithm>
#include <cmath>
#include <cstring>
#include <cstdio>
#include <unordered_set>

// Full solver: K-nearest auction + violation refinement, all in C++.
// cost is row-major n*n float64. rowsol[i] = column.
extern "C" int solve_assignment(int n, const double* cost, int* rowsol) {
    const int N = n;
    const int K0 = 48;
    const double TOL = 1e-9;
    const double EPS_FINAL = 1e-10;

    // candidate lists
    std::vector<std::vector<int>> cands(N);
    std::vector<int> idx(N);
    for (int i = 0; i < N; ++i) {
        const double* row = cost + (size_t)i * N;
        for (int j = 0; j < N; ++j) idx[j] = j;
        std::nth_element(idx.begin(), idx.begin() + K0, idx.end(),
                         [&](int a, int b) { return row[a] < row[b]; });
        cands[i].assign(idx.begin(), idx.begin() + K0);
    }

    std::vector<double> price(N, 0.0);
    std::vector<int> owner(N);
    std::vector<int> assign(N);
    std::vector<int> free_list(N);
    std::vector<double> u(N);
    std::vector<int> flat_idx;
    std::vector<double> flat_cost;
    flat_idx.reserve((size_t)N * K0 * 2);
    flat_cost.reserve((size_t)N * K0 * 2);

    auto run_auction = [&](double eps_final) -> int {
        int K = 0;
        for (int i = 0; i < N; ++i) K = std::max(K, (int)cands[i].size());
        flat_idx.assign((size_t)N * K, -1);
        flat_cost.assign((size_t)N * K, 0.0);
        double cmax = 0;
        for (int i = 0; i < N; ++i) {
            const double* row = cost + (size_t)i * N;
            for (int k = 0; k < (int)cands[i].size(); ++k) {
                int j = cands[i][k];
                flat_idx[(size_t)i * K + k] = j;
                double c = row[j];
                flat_cost[(size_t)i * K + k] = c;
                if (c > cmax) cmax = c;
            }
        }
        std::fill(price.begin(), price.end(), 0.0);
        double eps = std::max(cmax / 4.0, 1e-3);
        int rounds = 0;
        while (rounds < 40) {
            ++rounds;
            std::fill(owner.begin(), owner.end(), -1);
            std::fill(assign.begin(), assign.end(), -1);
            int nfree = N;
            for (int i = 0; i < N; ++i) free_list[i] = i;
            int guard = 0;
            const int GUARD_MAX = N * 300;
            while (nfree > 0 && guard < GUARD_MAX) {
                ++guard;
                int i = free_list[--nfree];
                const int* cj = flat_idx.data() + (size_t)i * K;
                const double* cc = flat_cost.data() + (size_t)i * K;
                double v1 = -1e300, v2 = -1e300;
                int j1 = -1;
                for (int k = 0; k < K; ++k) {
                    int j = cj[k];
                    if (j < 0) break;
                    double val = -cc[k] - price[j];
                    if (val > v1) { v2 = v1; v1 = val; j1 = j; }
                    else if (val > v2) v2 = val;
                }
                if (j1 < 0) return 3;
                if (v2 < -1e200) v2 = v1 - 1.0;
                price[j1] += (v1 - v2) + eps;
                int prev = owner[j1];
                owner[j1] = i;
                assign[i] = j1;
                if (prev >= 0) {
                    assign[prev] = -1;
                    free_list[nfree++] = prev;
                }
            }
            if (nfree == 0) {
                if (eps <= eps_final) {
                    for (int i = 0; i < N; ++i) rowsol[i] = assign[i];
                    return 0;
                }
                eps *= 0.2;
                if (eps < eps_final) eps = eps_final;
            } else {
                eps *= 0.2;
                if (eps < eps_final) return 1;
            }
        }
        return 2;
    };

    for (int it = 0; it < 8; ++it) {
        int rc = run_auction(EPS_FINAL);
        if (rc != 0) return rc;
        for (int i = 0; i < N; ++i) {
            int j = rowsol[i];
            u[i] = -cost[(size_t)i * N + j] - price[j];
        }
        // find violations and add them
        int added = 0;
        // membership via linear scan is ok if lists stay small; use a mark array per row only when list large
        std::vector<char> in(N);
        for (int i = 0; i < N; ++i) {
            std::fill(in.begin(), in.end(), 0);
            for (int j : cands[i]) in[j] = 1;
            const double* row = cost + (size_t)i * N;
            double ui = u[i];
            for (int j = 0; j < N; ++j) {
                if (in[j]) continue;
                if (row[j] + ui + price[j] < -TOL) {
                    cands[i].push_back(j);
                    in[j] = 1;
                    ++added;
                }
            }
        }
        if (added == 0) return 0;
    }
    return 4;
}
