// Cost-scaling assignment (push-relabel style) for dense bipartite min-cost matching.
// Based on the algorithm of Goldberg & Kennedy, specialized to assignment.
// Costs are scaled to int64.
#include <vector>
#include <cstdint>
#include <algorithm>
#include <cmath>
#include <cstring>
#include <cstdio>
#include <queue>

extern "C" int cs_solve(int n, const double* cost, int* rowsol) {
    const int N = n;
    // scale
    const double SCALE = 1e9;
    auto C = [&](int i, int j) -> int64_t {
        return (int64_t)std::llround(cost[(size_t)i * (size_t)N + j] * SCALE);
    };

    // potentials of columns (prices). Row potentials implicit.
    std::vector<int64_t> price(N, 0);
    std::vector<int> owner(N, -1);     // row matched to column
    std::vector<int> match(N, -1);     // column matched to row

    // epsilon = max cost initially
    int64_t maxc = 1;
    for (int i = 0; i < N; i += 3) {
        const double* row = cost + (size_t)i * N;
        for (int j = 0; j < N; j += 3) maxc = std::max(maxc, (int64_t)std::llround(row[j] * SCALE));
    }
    int64_t eps = 1;
    while (eps < maxc) eps <<= 1;

    std::vector<int64_t> dist(N);
    std::vector<int> pred(N);
    std::vector<char> vis(N);

    // For each scale, run auction-like epsilon-optimal refinement via push of free rows
    // using Dijkstra on admissible (reduced cost < eps) ... we'll do cost-scaling SSP:
    // at each scale, refine prices so reduced costs are > -eps, using a scaling push.
    // Implementation: epsilon-scaling auction (Bertsekas) but with integer costs and
    // a heap so each bid is O(log n) after an O(n) scan. Same complexity as before.
    // Instead, use the "scaling push-relabel" with admissible edges only (reduced cost == 0 after scaling).

    // We'll implement the classic "assignment cost scaling" from Goldberg:
    // maintain epsilon-optimality: c_ij - u_i - v_j >= -eps for unmatched residual, 0 for matched.
    // Start eps large. Refine by pushing along admissible arcs (reduced cost < 0? <= 0).

    std::vector<int64_t> u(N, 0), v(N, 0);
    std::vector<int> row_of_col(N, -1);
    std::vector<int> col_of_row(N, -1);

    auto reduced = [&](int i, int j) -> int64_t {
        return C(i, j) - u[i] - v[j];
    };

    // initialize v as column mins so reduced >= 0 at eps = max
    for (int j = 0; j < N; ++j) {
        int64_t mn = C(0, j);
        for (int i = 1; i < N; ++i) mn = std::min(mn, C(i, j));
        v[j] = mn;
    }

    // active rows (with excess)
    std::vector<int> excess_row(N, 1); // each row starts with 1 unit to push
    std::vector<int> stack;
    stack.reserve(N);
    for (int i = N - 1; i >= 0; --i) stack.push_back(i);

    int64_t cur_eps = eps;
    int refine_passes = 0;
    while (cur_eps > 0) {
        // refine: while there is a row with excess, push along an admissible edge
        // admissible: reduced cost < 0? For eps-optimality we allow reduced >= -cur_eps,
        // admissible for pushing (forward) if reduced < 0 (strict) after price updates... 
        // Standard double-push: admissible if c_p(i,j) < 0 where prices scaled.
        // Simpler robust approach: at this scale, run Hungarian augmentation but only
        // consider edges with reduced cost <= cur_eps, using Dijkstra with potentials.
        // If the sparse graph has no perfect matching, lower eps and add prices.
        // This is "cost scaling" via thresholded successive shortest paths.

        // Build nothing; scan.
        // Reset matching? No, keep previous matching and only reassign free rows.
        // After a scale, some matched edges may have reduced cost > 0; unmatch those? 
        // For thresholded SSP we keep a feasible matching (partial) of tight-enough edges.

        // Unmatch edges that are not epsilon-optimal (reduced > 0 is fine for matched? 
        // matched edges should have reduced cost == 0 in complementary slackness, but with scaling
        // we allow -cur_eps <= reduced <= cur_eps).
        for (int i = 0; i < N; ++i) {
            int j = col_of_row[i];
            if (j >= 0) {
                int64_t rc = C(i, j) - u[i] - v[j];
                if (rc > cur_eps || rc < -cur_eps) {
                    col_of_row[i] = -1;
                    row_of_col[j] = -1;
                }
            }
        }

        // Augment free rows using Dijkstra restricted to edges with reduced cost <= cur_eps
        // and reverse matched edges.
        std::vector<int> free_rows;
        for (int i = 0; i < N; ++i) if (col_of_row[i] < 0) free_rows.push_back(i);

        bool failed = false;
        for (int fi = 0; fi < (int)free_rows.size(); ++fi) {
            int src = free_rows[fi];
            if (col_of_row[src] >= 0) continue;
            std::fill(dist.begin(), dist.end(), INT64_MAX / 4);
            std::fill(pred.begin(), pred.end(), -1);
            std::fill(vis.begin(), vis.end(), 0);
            using P = std::pair<int64_t, int>;
            std::priority_queue<P, std::vector<P>, std::greater<P>> pq;
            // edges from src
            for (int j = 0; j < N; ++j) {
                int64_t rc = C(src, j) - u[src] - v[j];
                if (rc <= cur_eps) {
                    int64_t d = std::max<int64_t>(rc, 0); // pay only positive reduced?
                    // For shortest path of reduced costs, use rc directly (can be negative down to -cur_eps).
                    // Shift by cur_eps to make nonnegative: weight = rc + cur_eps >= 0 for admissible.
                    int64_t w = rc + cur_eps;
                    if (w < dist[j]) { dist[j] = w; pred[j] = src; pq.emplace(w, j); }
                }
            }
            int sink = -1;
            while (!pq.empty()) {
                auto [d, j] = pq.top(); pq.pop();
                if (vis[j] || d != dist[j]) continue;
                vis[j] = 1;
                if (row_of_col[j] < 0) { sink = j; break; }
                int i2 = row_of_col[j];
                int64_t rc_matched = C(i2, j) - u[i2] - v[j];
                for (int j2 = 0; j2 < N; ++j2) {
                    if (vis[j2]) continue;
                    int64_t rc = C(i2, j2) - u[i2] - v[j2];
                    if (rc > cur_eps) continue;
                    int64_t w = rc + cur_eps;
                    int64_t nd = dist[j] + w - (rc_matched + cur_eps);
                    if (nd < dist[j2]) {
                        dist[j2] = nd;
                        pred[j2] = i2;
                        pq.emplace(nd, j2);
                    }
                }
            }
            if (sink < 0) { failed = true; break; }
            // update potentials: v[j] += dist[j] - dist[sink] for visited? 
            int64_t ds = dist[sink];
            for (int j = 0; j < N; ++j) if (vis[j]) v[j] += dist[j] - ds;
            // augment
            int j = sink;
            while (true) {
                int i2 = pred[j];
                int prev = col_of_row[i2];
                col_of_row[i2] = j;
                row_of_col[j] = i2;
                if (i2 == src) break;
                j = prev;
            }
            // refresh u for matched rows to keep matched reduced cost 0
            // u[i] = C(i, match) - v[match]
            for (int i = 0; i < N; ++i) {
                int j = col_of_row[i];
                if (j >= 0) u[i] = C(i, j) - v[j];
            }
        }
        ++refine_passes;
        if (failed) {
            // scale not fine enough for this threshold graph; shouldn't happen if cur_eps starts at max
            // and we only decrease. If it fails, increase candidates by not thresholding — fall back.
            return 5;
        }
        if (cur_eps == 1) break;
        cur_eps = std::max<int64_t>(cur_eps / 2, 1);
        // price refinement: v stays, u refreshed
    }
    for (int i = 0; i < N; ++i) rowsol[i] = col_of_row[i];
    return 0;
}
