// Sparse Jonker-Volgenant for the assignment problem.
// Each row has a sorted-or-unsorted candidate list. Costs are looked up from the dense matrix
// only for candidates. Columns not in any list are absent.
// If the candidate graph has no perfect matching the function returns 1.
//
// row_ptr: CSR row pointer length n+1
// cols: column indices
// cost: dense row-major, used to read edge costs (so we don't duplicate)
#include <vector>
#include <cstdint>
#include <algorithm>
#include <cstring>
#include <cmath>

static constexpr double BIG = 1e100;

extern "C" int lapjv_sparse(int n, const double* cost,
                            const int* row_ptr, const int* col_idx,
                            int* rowsol) {
    const int N = n;
    std::vector<int> x(N, -1), y(N, -1);
    std::vector<double> u(N, 0.0), v(N, 0.0);
    std::vector<int> pred(N, -1);
    std::vector<double> d(N);
    std::vector<int> free(N);
    std::vector<char> in_tree(N);

    auto C = [&](int i, int j) -> double { return cost[(size_t)i * N + j]; };

    // adjacency of columns -> rows (reverse), built from CSR
    std::vector<std::vector<int>> col_rows(N);
    for (int i = 0; i < N; ++i) {
        for (int p = row_ptr[i]; p < row_ptr[i + 1]; ++p) col_rows[col_idx[p]].push_back(i);
    }

    // column reduction over existing edges
    for (int j = N - 1; j >= 0; --j) {
        if (col_rows[j].empty()) return 2;
        double minv = BIG;
        int imin = -1;
        for (int i : col_rows[j]) {
            double val = C(i, j);
            if (val < minv) { minv = val; imin = i; }
        }
        v[j] = minv;
        if (x[imin] == -1) { x[imin] = j; y[j] = imin; }
    }

    int nfree = 0;
    for (int i = 0; i < N; ++i) {
        if (x[i] == -1) free[nfree++] = i;
        else {
            int j1 = x[i];
            double minv = BIG;
            for (int p = row_ptr[i]; p < row_ptr[i + 1]; ++p) {
                int j = col_idx[p];
                if (j == j1) continue;
                double red = C(i, j) - v[j];
                if (red < minv) minv = red;
            }
            if (minv < BIG / 2) v[j1] -= minv;
        }
    }

    // augmenting row reduction (2 phases)
    for (int phase = 0; phase < 2 && nfree; ++phase) {
        int k = 0, prv = nfree;
        nfree = 0;
        while (k < prv) {
            int i = free[k++];
            double umin = BIG, usub = BIG;
            int j1 = -1, j2 = -1;
            for (int p = row_ptr[i]; p < row_ptr[i + 1]; ++p) {
                int j = col_idx[p];
                double h = C(i, j) - v[j];
                if (h < usub) {
                    if (h >= umin) { usub = h; j2 = j; }
                    else { usub = umin; umin = h; j2 = j1; j1 = j; }
                }
            }
            if (j1 < 0) return 3;
            int i0 = y[j1];
            if (umin < usub) v[j1] -= (usub - umin);
            else if (i0 >= 0 && j2 >= 0) { j1 = j2; i0 = y[j1]; }
            x[i] = j1;
            y[j1] = i;
            if (i0 >= 0) {
                x[i0] = -1;
                if (umin < usub) free[nfree++] = i0;
                else free[prv++] = i0;
            }
        }
    }

    std::fill(x.begin(), x.end(), -1);
    for (int j = 0; j < N; ++j) if (y[j] >= 0) x[y[j]] = j;
    nfree = 0;
    for (int i = 0; i < N; ++i) if (x[i] < 0) free[nfree++] = i;

    // augmentation: Dijkstra over sparse residual
    std::vector<int> touch(N);
    int stamp = 0;
    std::vector<int> heap_j;
    std::vector<double> heap_d;
    auto heap_swap = [&](int a, int b) {
        std::swap(heap_j[a], heap_j[b]);
        std::swap(heap_d[a], heap_d[b]);
    };
    auto heap_up = [&](int p) {
        while (p > 0) {
            int parent = (p - 1) >> 1;
            if (heap_d[p] < heap_d[parent]) { heap_swap(p, parent); p = parent; }
            else break;
        }
    };
    auto heap_down = [&](int p) {
        int sz = (int)heap_j.size();
        while (true) {
            int l = p * 2 + 1, r = l + 1, best = p;
            if (l < sz && heap_d[l] < heap_d[best]) best = l;
            if (r < sz && heap_d[r] < heap_d[best]) best = r;
            if (best == p) break;
            heap_swap(p, best);
            p = best;
        }
    };

    for (int f = 0; f < nfree; ++f) {
        int freerow = free[f];
        ++stamp;
        if (stamp == 0) { std::fill(touch.begin(), touch.end(), 0); stamp = 1; }
        heap_j.clear();
        heap_d.clear();
        std::fill(pred.begin(), pred.end(), -1);
        // init from free row
        for (int p = row_ptr[freerow]; p < row_ptr[freerow + 1]; ++p) {
            int j = col_idx[p];
            double dj = C(freerow, j) - v[j];
            d[j] = dj;
            pred[j] = freerow;
            touch[j] = stamp;
            heap_j.push_back(j);
            heap_d.push_back(dj);
            heap_up((int)heap_j.size() - 1);
        }
        int endofpath = -1;
        std::vector<int> scanned;
        scanned.reserve(64);
        while (!heap_j.empty()) {
            double mind = heap_d[0];
            int j = heap_j[0];
            heap_swap(0, (int)heap_j.size() - 1);
            heap_j.pop_back();
            heap_d.pop_back();
            if (!heap_j.empty()) heap_down(0);
            if (touch[j] != stamp) continue;
            // stale?
            if (d[j] != mind && std::abs(d[j] - mind) > 0) {
                // may be stale entry
                if (mind > d[j] + 1e-15) continue;
            }
            if (y[j] < 0) { endofpath = j; break; }
            scanned.push_back(j);
            int i = y[j];
            double u_i = C(i, j) - v[j];
            for (int p = row_ptr[i]; p < row_ptr[i + 1]; ++p) {
                int j2 = col_idx[p];
                double nd = mind + (C(i, j2) - v[j2] - u_i);
                if (touch[j2] != stamp || nd < d[j2]) {
                    d[j2] = nd;
                    pred[j2] = i;
                    touch[j2] = stamp;
                    heap_j.push_back(j2);
                    heap_d.push_back(nd);
                    heap_up((int)heap_j.size() - 1);
                }
            }
        }
        if (endofpath < 0) return 4;
        double mind = d[endofpath];
        for (int j : scanned) v[j] += d[j] - mind;
        int j = endofpath;
        while (true) {
            int i = pred[j];
            y[j] = i;
            int jnext = x[i];
            x[i] = j;
            j = jnext;
            if (i == freerow) break;
        }
    }
    for (int i = 0; i < N; ++i) rowsol[i] = x[i];
    return 0;
}
