// Build candidate edges: all entries <= thr, plus ensure each row has at least Kmin
// candidates (the Kmin smallest if the threshold yields fewer).
// Returns via row_ptr (n+1), cols (filled, capacity must be enough). Returns nnz.
extern "C" int build_candidates(int n, const double* cost, double thr, int Kmin,
                                int* row_ptr, int* cols, int cols_cap) {
    const int N = n;
    std::vector<int> tmp(N);
    int nnz = 0;
    row_ptr[0] = 0;
    for (int i = 0; i < N; ++i) {
        const double* row = cost + (size_t)i * N;
        int cnt = 0;
        for (int j = 0; j < N; ++j) {
            if (row[j] <= thr) {
                if (nnz >= cols_cap) return -1;
                cols[nnz++] = j;
                ++cnt;
            }
        }
        if (cnt < Kmin) {
            // take Kmin smallest, merge
            for (int j = 0; j < N; ++j) tmp[j] = j;
            std::nth_element(tmp.begin(), tmp.begin() + Kmin, tmp.end(),
                             [&](int a, int b) { return row[a] < row[b]; });
            // mark already taken
            std::vector<char> have(N, 0);
            for (int p = row_ptr[i]; p < nnz; ++p) have[cols[p]] = 1;
            for (int k = 0; k < Kmin; ++k) {
                int j = tmp[k];
                if (!have[j]) {
                    if (nnz >= cols_cap) return -1;
                    cols[nnz++] = j;
                }
            }
        }
        row_ptr[i + 1] = nnz;
    }
    return nnz;
}

