#include <algorithm>
#include <cstring>
#include <cmath>
#include <cstdio>

// Sparse forward auction on a CSR graph. cost looked up from dense matrix.
// eps-scaling. Returns 0 if a perfect assignment within the candidate graph is found.
extern "C" int auction_sparse(int n, const double* cost,
                              const int* row_ptr, const int* col_idx,
                              int* rowsol, double eps_final) {
    const int N = n;
    std::vector<double> price(N, 0.0);
    std::vector<int> owner(N, -1);
    std::vector<int> assign(N, -1);
    std::vector<int> free_list(N);

    double cmax = 0;
    for (int i = 0; i < N; ++i)
        for (int p = row_ptr[i]; p < row_ptr[i + 1]; ++p)
            cmax = std::max(cmax, cost[(size_t)i * N + col_idx[p]]);
    double eps = std::max(cmax / 2.0, 1e-3);

    int rounds = 0;
    while (rounds < 60) {
        ++rounds;
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        int nfree = N;
        for (int i = 0; i < N; ++i) free_list[i] = i;
        long long bids = 0;
        const long long BID_MAX = (long long)N * 400;
        while (nfree > 0 && bids < BID_MAX) {
            ++bids;
            int i = free_list[--nfree];
            double v1 = -1e300, v2 = -1e300;
            int j1 = -1;
            const double* row = cost + (size_t)i * N;
            for (int p = row_ptr[i]; p < row_ptr[i + 1]; ++p) {
                int j = col_idx[p];
                double val = -row[j] - price[j];
                if (val > v1) { v2 = v1; v1 = val; j1 = j; }
                else if (val > v2) v2 = val;
            }
            if (j1 < 0) return 3;
            if (v2 < -1e200) v2 = v1 - 1.0;
            price[j1] += (v1 - v2) + eps;
            int prev = owner[j1];
            owner[j1] = i;
            assign[i] = j1;
            if (prev >= 0) {
                assign[prev] = -1;
                free_list[nfree++] = prev;
            }
        }
        if (nfree == 0) {
            if (eps <= eps_final) {
                for (int i = 0; i < N; ++i) rowsol[i] = assign[i];
                return 0;
            }
            eps *= 0.2;
            if (eps < eps_final) eps = eps_final;
        } else {
            eps *= 0.2;
            if (eps < eps_final) {
                for (int i = 0; i < N; ++i) rowsol[i] = assign[i];
                return 1;
            }
        }
    }
    for (int i = 0; i < N; ++i) rowsol[i] = assign[i];
    return 2;
}
