#include <vector>
#include <cstdint>
#include <algorithm>
#include <cstring>
#include <cmath>
#include <cstdio>

struct AuctionResult {
    std::vector<double> price;
    std::vector<int> assign;
    int rc;
};

static AuctionResult auction_on(int N, const double* cost,
                                const std::vector<std::vector<int>>& cands,
                                double eps_final) {
    AuctionResult R;
    R.price.assign(N, 0.0);
    R.assign.assign(N, -1);
    std::vector<int> owner(N, -1);
    std::vector<int> free_list(N);
    double cmax = 0;
    for (int i = 0; i < N; ++i)
        for (int j : cands[i]) cmax = std::max(cmax, cost[(size_t)i * N + j]);
    double eps = std::max(cmax / 2.0, 1e-3);
    int rounds = 0;
    R.rc = 2;
    while (rounds < 50) {
        ++rounds;
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(R.assign.begin(), R.assign.end(), -1);
        int nfree = N;
        for (int i = 0; i < N; ++i) free_list[i] = i;
        long long bids = 0;
        const long long BID_MAX = (long long)N * 500;
        while (nfree > 0 && bids < BID_MAX) {
            ++bids;
            int i = free_list[--nfree];
            double v1 = -1e300, v2 = -1e300;
            int j1 = -1;
            const double* row = cost + (size_t)i * N;
            for (int j : cands[i]) {
                double val = -row[j] - R.price[j];
                if (val > v1) { v2 = v1; v1 = val; j1 = j; }
                else if (val > v2) v2 = val;
            }
            if (j1 < 0) { R.rc = 3; return R; }
            if (v2 < -1e200) v2 = v1 - 1.0;
            R.price[j1] += (v1 - v2) + eps;
            int prev = owner[j1];
            owner[j1] = i;
            R.assign[i] = j1;
            if (prev >= 0) {
                R.assign[prev] = -1;
                free_list[nfree++] = prev;
            }
        }
        if (nfree == 0) {
            if (eps <= eps_final) { R.rc = 0; return R; }
            eps *= 0.25;
            if (eps < eps_final) eps = eps_final;
        } else {
            eps *= 0.25;
            if (eps < eps_final) { R.rc = 1; return R; }
        }
    }
    return R;
}

extern "C" int solve_refine(int n, const double* cost, int* rowsol) {
    const int N = n;
    const double THR = 0.22;
    const int KMIN = 32;
    const double TOL = 1e-8;

    std::vector<std::vector<int>> cands(N);
    std::vector<char> in(N);
    std::vector<int> tmp(N);
    for (int i = 0; i < N; ++i) {
        const double* row = cost + (size_t)i * N;
        cands[i].reserve(64);
        int cnt = 0;
        for (int j = 0; j < N; ++j) if (row[j] <= THR) { cands[i].push_back(j); ++cnt; }
        if (cnt < KMIN) {
            for (int j = 0; j < N; ++j) tmp[j] = j;
            std::nth_element(tmp.begin(), tmp.begin() + KMIN, tmp.end(),
                             [&](int a, int b) { return row[a] < row[b]; });
            std::fill(in.begin(), in.end(), 0);
            for (int j : cands[i]) in[j] = 1;
            for (int k = 0; k < KMIN; ++k) if (!in[tmp[k]]) cands[i].push_back(tmp[k]);
        }
    }

    for (int it = 0; it < 6; ++it) {
        AuctionResult R = auction_on(N, cost, cands, 1e-10);
        if (R.rc != 0) return R.rc;
        // dual u_i = -cost[i, assign] - price[assign]
        int added = 0;
        for (int i = 0; i < N; ++i) {
            int ja = R.assign[i];
            double ui = -cost[(size_t)i * N + ja] - R.price[ja];
            std::fill(in.begin(), in.end(), 0);
            for (int j : cands[i]) in[j] = 1;
            const double* row = cost + (size_t)i * N;
            for (int j = 0; j < N; ++j) {
                if (in[j]) continue;
                if (row[j] + ui + R.price[j] < -TOL) {
                    cands[i].push_back(j);
                    in[j] = 1;
                    ++added;
                }
            }
        }
        if (added == 0) {
            for (int i = 0; i < N; ++i) rowsol[i] = R.assign[i];
            return 0;
        }
    }
    return 4;
}
