// Forward-reverse auction (Bertsekas) for dense assignment, restricted to a
// candidate list per row, with reverse bids over the columns' incident edges.
#include <vector>
#include <cstdint>
#include <algorithm>
#include <cstring>
#include <cmath>
#include <cstdio>

extern "C" int fr_auction(int n, const double* cost, double thr, int Kmin,
                          int* rowsol, double eps_final) {
    const int N = n;
    std::vector<std::vector<int>> row_cands(N);
    std::vector<std::vector<int>> col_cands(N);
    std::vector<int> tmp(N);
    std::vector<char> in(N);
    for (int i = 0; i < N; ++i) {
        const double* row = cost + (size_t)i * N;
        int cnt = 0;
        for (int j = 0; j < N; ++j) if (row[j] <= thr) { row_cands[i].push_back(j); ++cnt; }
        if (cnt < Kmin) {
            for (int j = 0; j < N; ++j) tmp[j] = j;
            std::nth_element(tmp.begin(), tmp.begin() + Kmin, tmp.end(),
                             [&](int a, int b) { return row[a] < row[b]; });
            std::fill(in.begin(), in.end(), 0);
            for (int j : row_cands[i]) in[j] = 1;
            for (int k = 0; k < Kmin; ++k) if (!in[tmp[k]]) row_cands[i].push_back(tmp[k]);
        }
        for (int j : row_cands[i]) col_cands[j].push_back(i);
    }

    std::vector<double> price(N, 0.0);     // column prices
    std::vector<double> profit(N, 0.0);    // row profits (dual u, but sign: benefit)
    std::vector<int> owner(N, -1);         // row owning column
    std::vector<int> assign(N, -1);
    std::vector<int> free_rows;
    std::vector<int> free_cols;
    free_rows.reserve(N);
    for (int i = 0; i < N; ++i) free_rows.push_back(i);

    double eps = std::max(thr / 2.0, 1e-3);
    int rounds = 0;
    while (rounds < 40) {
        ++rounds;
        // FORWARD phase: assign all free rows
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        free_rows.clear();
        for (int i = 0; i < N; ++i) free_rows.push_back(i);
        long long bids = 0;
        bool fwd_ok = true;
        while (!free_rows.empty() && bids < (long long)N * 300) {
            ++bids;
            int i = free_rows.back(); free_rows.pop_back();
            double v1 = -1e300, v2 = -1e300;
            int j1 = -1;
            const double* row = cost + (size_t)i * N;
            for (int j : row_cands[i]) {
                double val = -row[j] - price[j];
                if (val > v1) { v2 = v1; v1 = val; j1 = j; }
                else if (val > v2) v2 = val;
            }
            if (j1 < 0) return 3;
            if (v2 < -1e200) v2 = v1 - 1.0;
            // bid increment
            double inc = (v1 - v2) + eps;
            price[j1] += inc;
            profit[i] = v1 - inc; // new profit equals second best - eps = v2 - eps? 
            // after price increase, benefit of j1 becomes v1 - inc = v2 - eps
            profit[i] = v2 - eps;
            int prev = owner[j1];
            owner[j1] = i;
            assign[i] = j1;
            if (prev >= 0) {
                assign[prev] = -1;
                free_rows.push_back(prev);
            }
        }
        if (!free_rows.empty()) { fwd_ok = false; }

        if (fwd_ok && eps <= eps_final) {
            // verify permutation
            for (int i = 0; i < N; ++i) rowsol[i] = assign[i];
            return 0;
        }

        // REVERSE phase: columns bid for rows, using profits as row prices.
        // A column is "unassigned" from its perspective if we restart matching from columns.
        // Reverse auction: objects (columns) bid for persons (rows).
        // Benefit of column j for row i: -cost - profit[i], column wants to minimize price it pays.
        // We reassign from scratch on the reverse.
        std::fill(assign.begin(), assign.end(), -1); // assign[i] = column
        std::vector<int> row_of(N, -1);
        free_cols.clear();
        for (int j = 0; j < N; ++j) free_cols.push_back(j);
        bids = 0;
        bool rev_ok = true;
        while (!free_cols.empty() && bids < (long long)N * 300) {
            ++bids;
            int j = free_cols.back(); free_cols.pop_back();
            double v1 = -1e300, v2 = -1e300;
            int i1 = -1;
            for (int i : col_cands[j]) {
                double val = -cost[(size_t)i * N + j] - profit[i];
                if (val > v1) { v2 = v1; v1 = val; i1 = i; }
                else if (val > v2) v2 = val;
            }
            if (i1 < 0) { rev_ok = false; break; }
            if (v2 < -1e200) v2 = v1 - 1.0;
            double inc = (v1 - v2) + eps;
            profit[i1] += inc;
            // column price becomes consistent: price[j] = -cost - profit_after? 
            // benefit of i1 for j after profit increase: v1 - inc = v2 - eps
            // price_j should satisfy -cost[i1,j] - price[j] = profit[i1] on assignment, 
            // so price[j] = -cost[i1,j] - profit[i1]
            price[j] = -cost[(size_t)i1 * N + j] - profit[i1];
            int prev_col = assign[i1];
            assign[i1] = j;
            if (prev_col >= 0) free_cols.push_back(prev_col);
        }
        if ((int)free_cols.size() != 0) rev_ok = false;

        if (!fwd_ok && !rev_ok) {
            eps *= 0.25;
            if (eps < eps_final) return 1;
            continue;
        }
        eps *= 0.25;
        if (eps < eps_final) eps = eps_final;
        // if reverse succeeded and eps is final, accept reverse assignment
        if (rev_ok && eps <= eps_final) {
            for (int i = 0; i < N; ++i) rowsol[i] = assign[i];
            // check permutation
            return 0;
        }
    }
    return 2;
}
