extern "C" int auction_fast(int n, const double* cost, double thr, int Kmin,
                            int* rowsol, double eps_final, double eps_factor) {
    const int N = n;
    using clk = std::chrono::high_resolution_clock;
    auto T0 = clk::now();
    std::vector<std::vector<int>> cands(N);
    std::vector<int> tmp(N);
    std::vector<char> in(N);
    for (int i = 0; i < N; ++i) {
        const double* row = cost + (size_t)i * N;
        int cnt = 0;
        cands[i].reserve(80);
        for (int j = 0; j < N; ++j) if (row[j] <= thr) { cands[i].push_back(j); ++cnt; }
        if (cnt < Kmin) {
            for (int j = 0; j < N; ++j) tmp[j] = j;
            std::nth_element(tmp.begin(), tmp.begin() + Kmin, tmp.end(),
                             [&](int a, int b) { return row[a] < row[b]; });
            std::fill(in.begin(), in.end(), 0);
            for (int j : cands[i]) in[j] = 1;
            for (int k = 0; k < Kmin; ++k) if (!in[tmp[k]]) cands[i].push_back(tmp[k]);
        }
    }
    double ms_build = std::chrono::duration<double, std::milli>(clk::now() - T0).count();

    std::vector<double> price(N, 0.0);
    std::vector<int> owner(N, -1), assign(N, -1), free_list(N);
    double eps = std::max(thr / 2.0, 1e-3);
    int rounds = 0;
    long long total_bids = 0;
    auto T1 = clk::now();
    while (rounds < 40) {
        ++rounds;
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        int nfree = N;
        for (int i = 0; i < N; ++i) free_list[i] = i;
        long long bids = 0;
        while (nfree > 0 && bids < (long long)N * 400) {
            ++bids;
            int i = free_list[--nfree];
            double v1 = -1e300, v2 = -1e300;
            int j1 = -1;
            const double* row = cost + (size_t)i * N;
            for (int j : cands[i]) {
                double val = -row[j] - price[j];
                if (val > v1) { v2 = v1; v1 = val; j1 = j; }
                else if (val > v2) v2 = val;
            }
            if (j1 < 0) return 3;
            if (v2 < -1e200) v2 = v1 - 1.0;
            price[j1] += (v1 - v2) + eps;
            int prev = owner[j1];
            owner[j1] = i;
            assign[i] = j1;
            if (prev >= 0) { assign[prev] = -1; free_list[nfree++] = prev; }
        }
        total_bids += bids;
        if (nfree == 0) {
            if (eps <= eps_final) {
                double ms = std::chrono::duration<double, std::milli>(clk::now() - T1).count();
                std::fprintf(stderr, "build %.2f auc %.2f rounds %d bids %lld eps %g factor %g\n",
                             ms_build, ms, rounds, total_bids, eps, eps_factor);
                for (int i = 0; i < N; ++i) rowsol[i] = assign[i];
                return 0;
            }
            eps *= eps_factor;
            if (eps < eps_final) eps = eps_final;
        } else {
            eps *= eps_factor;
            if (eps < eps_final) return 1;
        }
    }
    return 2;
}
