#include <vector>
#include <cstdint>
#include <algorithm>
#include <cstring>
#include <cmath>
#include <cstdio>
#include <chrono>

extern "C" int auction_keep(int n, const double* cost, double thr, int Kmin,
                            int* rowsol, double eps_final, double eps_factor) {
    const int N = n;
    using clk = std::chrono::high_resolution_clock;
    auto T0 = clk::now();
    std::vector<std::vector<int>> cands(N);
    std::vector<int> tmp(N);
    std::vector<char> in(N);
    for (int i = 0; i < N; ++i) {
        const double* row = cost + (size_t)i * N;
        cands[i].reserve(96);
        int cnt = 0;
        for (int j = 0; j < N; ++j) if (row[j] <= thr) { cands[i].push_back(j); ++cnt; }
        if (cnt < Kmin) {
            for (int j = 0; j < N; ++j) tmp[j] = j;
            std::nth_element(tmp.begin(), tmp.begin() + Kmin, tmp.end(),
                             [&](int a, int b) { return row[a] < row[b]; });
            std::fill(in.begin(), in.end(), 0);
            for (int j : cands[i]) in[j] = 1;
            for (int k = 0; k < Kmin; ++k) if (!in[tmp[k]]) cands[i].push_back(tmp[k]);
        }
    }
    double ms_build = std::chrono::duration<double, std::milli>(clk::now() - T0).count();

    std::vector<double> price(N, 0.0);
    std::vector<int> owner(N, -1), free_list(N);
    double eps = std::max(thr * 0.25, 1e-3);
    int rounds = 0;
    long long total_bids = 0;
    auto T1 = clk::now();
    // start with everyone free
    int nfree = N;
    for (int i = 0; i < N; ++i) free_list[i] = i;

    while (rounds < 60) {
        ++rounds;
        long long bids = 0;
        while (nfree > 0 && bids < (long long)N * 800) {
            ++bids;
            int i = free_list[--nfree];
            double v1 = -1e300, v2 = -1e300;
            int j1 = -1;
            const double* row = cost + (size_t)i * N;
            for (int j : cands[i]) {
                double val = -row[j] - price[j];
                if (val > v1) { v2 = v1; v1 = val; j1 = j; }
                else if (val > v2) v2 = val;
            }
            if (j1 < 0) return 3;
            if (v2 < -1e200) v2 = v1 - 1.0;
            double inc = (v1 - v2) + eps;
            // only bid if we need to raise price (always, by eps at least)
            price[j1] += inc;
            int prev = owner[j1];
            owner[j1] = i;
            if (prev >= 0 && prev != i) free_list[nfree++] = prev;
        }
        total_bids += bids;
        if (nfree > 0) {
            // couldn't finish at this eps; reduce and retry free rows only (they're still free)
            eps *= eps_factor;
            if (eps < eps_final) return 1;
            continue;
        }
        if (eps <= eps_final) {
            double ms = std::chrono::duration<double, std::milli>(clk::now() - T1).count();
            std::fprintf(stderr, "build %.2f auc %.2f rounds %d bids %lld\\n", ms_build, ms, rounds, total_bids);
            for (int j = 0; j < N; ++j) if (owner[j] >= 0) rowsol[owner[j]] = j;
            return 0;
        }
        // scale down eps. To restore eps-complementary slackness we must allow
        // re-bidding. Unassign everyone whose bid margin is now insufficient:
        // simplest correct approach: unassign all and keep prices (warm start).
        // But that's the slow path. Instead unassign all but keep prices — prices
        // are already high so re-bidding should be few if we only displace when
        // the current owner is not still best by eps.
        // Check each assigned row: if best - second < current margin, keep.
        // We'll just re-run with prices warm by unassigning all. Measure bids.
        std::fill(owner.begin(), owner.end(), -1);
        nfree = N;
        for (int i = 0; i < N; ++i) free_list[i] = i;
        eps *= eps_factor;
        if (eps < eps_final) eps = eps_final;
    }
    return 2;
}
