// Optimized dense LAPJV (Jonker-Volgenant) with cached row pointers.
#include <vector>
#include <cstdint>
#include <algorithm>
#include <cstring>
#include <cmath>
#include <cstdio>
#include <chrono>

extern "C" int lap_fast(int n, const double* cost, int* rowsol) {
    using clk = std::chrono::high_resolution_clock;
    auto T0 = clk::now();
    const int N = n;
    const double BIG = 1e100;
    std::vector<const double*> rows(N);
    for (int i = 0; i < N; ++i) rows[i] = cost + (size_t)i * N;

    std::vector<int> x(N, -1), y(N, -1);
    std::vector<double> v(N, 0.0), d(N);
    std::vector<int> pred(N), col(N), free_rows(N);

    // column reduction
    for (int j = N - 1; j >= 0; --j) {
        double minv = rows[0][j];
        int imin = 0;
        for (int i = 1; i < N; ++i) {
            double val = rows[i][j];
            if (val < minv) { minv = val; imin = i; }
        }
        v[j] = minv;
        if (x[imin] < 0) { x[imin] = j; y[j] = imin; }
    }
    auto T1 = clk::now();

    int nfree = 0;
    for (int i = 0; i < N; ++i) {
        if (x[i] < 0) { free_rows[nfree++] = i; continue; }
        int j1 = x[i];
        const double* row = rows[i];
        double minv = BIG;
        for (int j = 0; j < N; ++j) {
            if (j == j1) continue;
            double red = row[j] - v[j];
            if (red < minv) minv = red;
        }
        v[j1] -= minv;
    }
    auto T2 = clk::now();

    for (int phase = 0; phase < 2 && nfree; ++phase) {
        int k = 0, prv = nfree;
        nfree = 0;
        while (k < prv) {
            int i = free_rows[k++];
            const double* row = rows[i];
            double umin = row[0] - v[0];
            int j1 = 0;
            double usub = BIG;
            int j2 = -1;
            for (int j = 1; j < N; ++j) {
                double h = row[j] - v[j];
                if (h < usub) {
                    if (h >= umin) { usub = h; j2 = j; }
                    else { usub = umin; umin = h; j2 = j1; j1 = j; }
                }
            }
            int i0 = y[j1];
            if (umin < usub) v[j1] -= (usub - umin);
            else if (i0 >= 0 && j2 >= 0) { j1 = j2; i0 = y[j1]; }
            x[i] = j1; y[j1] = i;
            if (i0 >= 0) {
                x[i0] = -1;
                if (umin < usub) free_rows[nfree++] = i0;
                else free_rows[prv++] = i0;
            }
        }
    }
    auto T3 = clk::now();

    std::fill(x.begin(), x.end(), -1);
    for (int j = 0; j < N; ++j) if (y[j] >= 0) x[y[j]] = j;
    nfree = 0;
    for (int i = 0; i < N; ++i) if (x[i] < 0) free_rows[nfree++] = i;

    // augmentation with a simple binary heap of column indices, dense init
    std::vector<int> heap;
    std::vector<int> hpos(N, -1);
    heap.reserve(N);
    auto hswap = [&](int a, int b) {
        int ja = heap[a], jb = heap[b];
        heap[a] = jb; heap[b] = ja;
        hpos[ja] = b; hpos[jb] = a;
    };
    auto hup = [&](int p) {
        while (p > 0) {
            int parent = (p - 1) >> 1;
            if (d[heap[p]] < d[heap[parent]]) { hswap(p, parent); p = parent; }
            else break;
        }
    };
    auto hdown = [&](int p) {
        int sz = (int)heap.size();
        while (true) {
            int l = p * 2 + 1, r = l + 1, best = p;
            if (l < sz && d[heap[l]] < d[heap[best]]) best = l;
            if (r < sz && d[heap[r]] < d[heap[best]]) best = r;
            if (best == p) break;
            hswap(p, best); p = best;
        }
    };
    auto hpush = [&](int j) {
        hpos[j] = (int)heap.size();
        heap.push_back(j);
        hup(hpos[j]);
    };
    auto hpop = [&]() {
        int j = heap[0];
        int last = heap.back();
        heap.pop_back();
        hpos[j] = -1;
        if (!heap.empty()) { heap[0] = last; hpos[last] = 0; hdown(0); }
        return j;
    };

    for (int f = 0; f < nfree; ++f) {
        int freerow = free_rows[f];
        const double* frow = rows[freerow];
        heap.clear();
        for (int j = 0; j < N; ++j) {
            d[j] = frow[j] - v[j];
            pred[j] = freerow;
            hpos[j] = j;
            heap.push_back(j);
        }
        // heapify
        for (int p = (N - 2) / 2; p >= 0; --p) hdown(p);

        int endofpath = -1;
        std::vector<int> scanned;
        scanned.reserve(64);
        while (!heap.empty()) {
            int j = hpop();
            double mind = d[j];
            if (y[j] < 0) { endofpath = j; break; }
            scanned.push_back(j);
            int i = y[j];
            const double* row = rows[i];
            double base = mind - (row[j] - v[j]);
            for (int j2 = 0; j2 < N; ++j2) {
                if (hpos[j2] < 0) continue;
                double nd = base + row[j2] - v[j2];
                if (nd < d[j2]) {
                    d[j2] = nd;
                    pred[j2] = i;
                    hup(hpos[j2]);
                }
            }
        }
        double mind = d[endofpath];
        for (int j : scanned) v[j] += d[j] - mind;
        int j = endofpath;
        while (true) {
            int i = pred[j];
            y[j] = i;
            int jnext = x[i];
            x[i] = j;
            j = jnext;
            if (i == freerow) break;
        }
    }
    auto T4 = clk::now();
    auto ms = [](auto a, auto b){ return std::chrono::duration<double,std::milli>(b-a).count(); };
    std::fprintf(stderr, "augs %d col %.2f red %.2f row %.2f aug %.2f total %.2f\n",
                 nfree, ms(T0,T1), ms(T1,T2), ms(T2,T3), ms(T3,T4), ms(T0,T4));
    for (int i = 0; i < N; ++i) rowsol[i] = x[i];
    return 0;
}
