#include <vector>
#include <cstdint>
#include <algorithm>
#include <cstring>
#include <cmath>
#include <cstdio>
#include <thread>
#include <chrono>

// Parallel Jacobi (synchronous) auction on a candidate graph.
extern "C" int auction_jacobi(int n, const double* cost, double thr, int Kmin,
                              int* rowsol, double eps_final, int nthreads) {
    const int N = n;
    using clk = std::chrono::high_resolution_clock;
    auto T0 = clk::now();
    std::vector<std::vector<int>> cands(N);
    std::vector<int> tmp(N);
    std::vector<char> in(N);
    for (int i = 0; i < N; ++i) {
        const double* row = cost + (size_t)i * N;
        cands[i].reserve(80);
        int cnt = 0;
        for (int j = 0; j < N; ++j) if (row[j] <= thr) { cands[i].push_back(j); ++cnt; }
        if (cnt < Kmin) {
            for (int j = 0; j < N; ++j) tmp[j] = j;
            std::nth_element(tmp.begin(), tmp.begin() + Kmin, tmp.end(),
                             [&](int a, int b) { return row[a] < row[b]; });
            std::fill(in.begin(), in.end(), 0);
            for (int j : cands[i]) in[j] = 1;
            for (int k = 0; k < Kmin; ++k) if (!in[tmp[k]]) cands[i].push_back(tmp[k]);
        }
    }
    double ms_build = std::chrono::duration<double, std::milli>(clk::now()-T0).count();

    std::vector<double> price(N, 0.0);
    std::vector<int> owner(N, -1);
    std::vector<int> bid_j(N), bid_prev_unused(N);
    std::vector<double> bid_inc(N);
    std::vector<char> is_free(N, 1);
    std::vector<int> free_list(N);
    int nfree = N;
    for (int i = 0; i < N; ++i) free_list[i] = i;

    if (nthreads < 1) nthreads = 1;
    double eps = std::max(thr / 2.0, 1e-3);
    int rounds = 0;
    long long total_bids = 0;
    auto T1 = clk::now();

    auto do_bids = [&](int tid) {
        int chunk = (nfree + nthreads - 1) / nthreads;
        int lo = tid * chunk, hi = std::min(nfree, lo + chunk);
        for (int t = lo; t < hi; ++t) {
            int i = free_list[t];
            double v1 = -1e300, v2 = -1e300;
            int j1 = -1;
            const double* row = cost + (size_t)i * N;
            for (int j : cands[i]) {
                double val = -row[j] - price[j];
                if (val > v1) { v2 = v1; v1 = val; j1 = j; }
                else if (val > v2) v2 = val;
            }
            if (v2 < -1e200) v2 = v1 - 1.0;
            bid_j[i] = j1;
            bid_inc[i] = (v1 - v2) + eps;
        }
    };

    while (rounds < 80) {
        ++rounds;
        int iter = 0;
        const int ITER_MAX = N * 4;
        while (nfree > 0 && iter < ITER_MAX) {
            ++iter;
            total_bids += nfree;
            if (nthreads == 1 || nfree < 64) {
                do_bids(0);
            } else {
                std::vector<std::thread> ts;
                ts.reserve(nthreads);
                for (int tid = 0; tid < nthreads; ++tid) ts.emplace_back(do_bids, tid);
                for (auto& th : ts) th.join();
            }
            // resolve conflicts: for each column, the highest increment bid wins
            // collect bids
            std::vector<int> winner(N, -1);
            std::vector<double> best_inc(N, -1.0);
            for (int t = 0; t < nfree; ++t) {
                int i = free_list[t];
                int j = bid_j[i];
                if (j < 0) return 3;
                if (bid_inc[i] > best_inc[j]) { best_inc[j] = bid_inc[i]; winner[j] = i; }
            }
            // apply
            std::vector<int> new_free;
            new_free.reserve(nfree);
            for (int j = 0; j < N; ++j) {
                int i = winner[j];
                if (i < 0) continue;
                price[j] += best_inc[j];
                int prev = owner[j];
                owner[j] = i;
                if (prev >= 0) new_free.push_back(prev);
            }
            // rows that bid but lost are still free
            std::vector<char> won(N, 0);
            for (int j = 0; j < N; ++j) if (winner[j] >= 0) won[winner[j]] = 1;
            for (int t = 0; t < nfree; ++t) {
                int i = free_list[t];
                if (!won[i]) new_free.push_back(i);
            }
            nfree = (int)new_free.size();
            for (int t = 0; t < nfree; ++t) free_list[t] = new_free[t];
        }
        if (nfree == 0 && eps <= eps_final) {
            double ms = std::chrono::duration<double, std::milli>(clk::now()-T1).count();
            std::fprintf(stderr, "build %.2f auc %.2f rounds %d bids %lld threads %d\n",
                         ms_build, ms, rounds, total_bids, nthreads);
            for (int j = 0; j < N; ++j) if (owner[j] >= 0) rowsol[owner[j]] = j;
            return 0;
        }
        if (nfree > 0) {
            eps *= 0.25;
            if (eps < eps_final) return 1;
        } else {
            // warm restart: unassign all, keep prices
            std::fill(owner.begin(), owner.end(), -1);
            nfree = N;
            for (int i = 0; i < N; ++i) free_list[i] = i;
            eps *= 0.25;
            if (eps < eps_final) eps = eps_final;
        }
    }
    return 2;
}
