#include <vector>
#include <cstdint>
#include <algorithm>
#include <cstring>
#include <cmath>
#include <cstdio>
#include <thread>
#include <chrono>
#include <atomic>

struct RowResult {
    double v1, v2;
    int j1;
};

extern "C" int auction_par(int n, const double* cost, double thr, int Kmin,
                           int* rowsol, double eps_final, int nthreads) {
    const int N = n;
    using clk = std::chrono::high_resolution_clock;
    auto T0 = clk::now();

    // store candidates as CSR for cache-friendly parallel scans
    std::vector<int> row_ptr(N + 1);
    std::vector<int> cols;
    cols.reserve((size_t)N * 80);
    std::vector<int> tmp(N);
    std::vector<char> in(N);
    row_ptr[0] = 0;
    for (int i = 0; i < N; ++i) {
        const double* row = cost + (size_t)i * N;
        int start = (int)cols.size();
        for (int j = 0; j < N; ++j) if (row[j] <= thr) cols.push_back(j);
        int cnt = (int)cols.size() - start;
        if (cnt < Kmin) {
            for (int j = 0; j < N; ++j) tmp[j] = j;
            std::nth_element(tmp.begin(), tmp.begin() + Kmin, tmp.end(),
                             [&](int a, int b) { return row[a] < row[b]; });
            std::fill(in.begin(), in.end(), 0);
            for (int p = start; p < (int)cols.size(); ++p) in[cols[p]] = 1;
            for (int k = 0; k < Kmin; ++k) if (!in[tmp[k]]) cols.push_back(tmp[k]);
        }
        row_ptr[i + 1] = (int)cols.size();
    }
    double ms_build = std::chrono::duration<double, std::milli>(clk::now()-T0).count();

    std::vector<double> price(N, 0.0);
    std::vector<int> owner(N, -1), free_list(N);
    std::vector<RowResult> results(N);
    if (nthreads < 1) nthreads = 1;

    double eps = std::max(thr / 2.0, 1e-3);
    int rounds = 0;
    long long total_bids = 0;
    auto T1 = clk::now();

    auto scan_range = [&](int lo, int hi, const int* fl, int nf) {
        for (int t = lo; t < hi; ++t) {
            int i = fl[t];
            const double* row = cost + (size_t)i * N;
            double v1 = -1e300, v2 = -1e300;
            int j1 = -1;
            for (int p = row_ptr[i]; p < row_ptr[i + 1]; ++p) {
                int j = cols[p];
                double val = -row[j] - price[j];
                if (val > v1) { v2 = v1; v1 = val; j1 = j; }
                else if (val > v2) v2 = val;
            }
            results[i] = {v1, v2, j1};
        }
    };

    while (rounds < 40) {
        ++rounds;
        std::fill(owner.begin(), owner.end(), -1);
        int nfree = N;
        for (int i = 0; i < N; ++i) free_list[i] = i;
        long long bids = 0;
        while (nfree > 0 && bids < (long long)N * 500) {
            // parallel scan of current free list, then serial apply in chunks
            // For Gauss-Seidel quality, apply immediately but scan in parallel batches.
            int batch = std::max(1, nfree);
            // scan all free in parallel (Jacobi-style read of prices), apply serially
            if (nthreads == 1) {
                scan_range(0, nfree, free_list.data(), nfree);
            } else {
                int chunk = (nfree + nthreads - 1) / nthreads;
                std::vector<std::thread> ts;
                for (int tid = 0; tid < nthreads; ++tid) {
                    int lo = tid * chunk, hi = std::min(nfree, lo + chunk);
                    if (lo < hi) ts.emplace_back(scan_range, lo, hi, free_list.data(), nfree);
                }
                for (auto& th : ts) th.join();
            }
            bids += nfree;
            // apply in order; a later row sees updated prices, so recompute if its target was updated
            std::vector<int> new_free;
            new_free.reserve(nfree);
            for (int t = 0; t < nfree; ++t) {
                int i = free_list[t];
                auto [v1, v2, j1] = results[i];
                // refresh if price changed: cheap check by recomputing benefit of j1
                const double* row = cost + (size_t)i * N;
                double cur = -row[j1] - price[j1];
                if (cur < v1 - 1e-15) {
                    // stale, recompute now
                    v1 = -1e300; v2 = -1e300; j1 = -1;
                    for (int p = row_ptr[i]; p < row_ptr[i + 1]; ++p) {
                        int j = cols[p];
                        double val = -row[j] - price[j];
                        if (val > v1) { v2 = v1; v1 = val; j1 = j; }
                        else if (val > v2) v2 = val;
                    }
                } else {
                    // second best might also be stale but only if it increased (prices only rise),
                    // so v2 is still a valid lower bound? Prices rose, so true v2 <= recorded v2.
                    // Using a larger v2 makes the bid smaller (more conservative) and can stall.
                    // Recompute v2 only. For correctness of eps-CS, bid must be at least eps above second.
                    // If recorded v2 is higher than true v2, inc is smaller, still >= eps if we add eps
                    // relative to recorded. That's still a valid auction bid (just less aggressive). OK.
                }
                if (j1 < 0) return 3;
                if (v2 < -1e200) v2 = v1 - 1.0;
                price[j1] += (v1 - v2) + eps;
                int prev = owner[j1];
                owner[j1] = i;
                if (prev >= 0) new_free.push_back(prev);
            }
            nfree = (int)new_free.size();
            for (int t = 0; t < nfree; ++t) free_list[t] = new_free[t];
        }
        total_bids += bids;
        if (nfree == 0 && eps <= eps_final) {
            double ms = std::chrono::duration<double, std::milli>(clk::now()-T1).count();
            std::fprintf(stderr, "build %.2f auc %.2f rounds %d bids %lld thr %d\n",
                         ms_build, ms, rounds, total_bids, nthreads);
            for (int j = 0; j < N; ++j) if (owner[j] >= 0) rowsol[owner[j]] = j;
            return 0;
        }
        eps *= 0.2;
        if (nfree > 0) {
            if (eps < eps_final) return 1;
        } else if (eps < eps_final) {
            eps = eps_final;
        }
    }
    return 2;
}
