// Sparse LAPJV. Candidates in CSR (row_ptr, col_idx). Costs from dense matrix.
// Shortest paths use a Dial-like bucket queue on scaled reduced costs, plus
// a dense column-adjacency built once.
#include <vector>
#include <cstdint>
#include <algorithm>
#include <cstring>
#include <cmath>
#include <cstdio>
#include <chrono>

extern "C" int lap_sparse(int n, const double* cost, const int* row_ptr, const int* col_idx, int* rowsol) {
    using clk = std::chrono::high_resolution_clock;
    auto T0 = clk::now();
    const int N = n;
    const double BIG = 1e100;

    std::vector<int> x(N, -1), y(N, -1);
    std::vector<double> v(N, 0.0), d(N);
    std::vector<int> pred(N, -1), free_rows(N);

    // reverse adjacency
    std::vector<int> col_ptr(N + 1, 0);
    int nnz = row_ptr[N];
    for (int p = 0; p < nnz; ++p) col_ptr[col_idx[p] + 1]++;
    for (int j = 0; j < N; ++j) col_ptr[j + 1] += col_ptr[j];
    std::vector<int> col_rows(nnz);
    std::vector<int> cursor(col_ptr.begin(), col_ptr.end());
    for (int i = 0; i < N; ++i) {
        for (int p = row_ptr[i]; p < row_ptr[i + 1]; ++p) {
            int j = col_idx[p];
            col_rows[cursor[j]++] = i;
        }
    }

    auto C = [&](int i, int j) -> double { return cost[(size_t)i * N + j]; };

    for (int j = N - 1; j >= 0; --j) {
        int a = col_ptr[j], b = col_ptr[j + 1];
        if (a == b) return 2;
        double minv = BIG;
        int imin = -1;
        for (int p = a; p < b; ++p) {
            int i = col_rows[p];
            double val = C(i, j);
            if (val < minv) { minv = val; imin = i; }
        }
        v[j] = minv;
        if (x[imin] < 0) { x[imin] = j; y[j] = imin; }
    }

    int nfree = 0;
    for (int i = 0; i < N; ++i) {
        if (x[i] < 0) { free_rows[nfree++] = i; continue; }
        int j1 = x[i];
        double minv = BIG;
        for (int p = row_ptr[i]; p < row_ptr[i + 1]; ++p) {
            int j = col_idx[p];
            if (j == j1) continue;
            double red = C(i, j) - v[j];
            if (red < minv) minv = red;
        }
        if (minv < BIG / 2) v[j1] -= minv;
    }

    for (int phase = 0; phase < 2 && nfree; ++phase) {
        int k = 0, prv = nfree;
        nfree = 0;
        while (k < prv) {
            int i = free_rows[k++];
            double umin = BIG, usub = BIG;
            int j1 = -1, j2 = -1;
            for (int p = row_ptr[i]; p < row_ptr[i + 1]; ++p) {
                int j = col_idx[p];
                double h = C(i, j) - v[j];
                if (h < usub) {
                    if (h >= umin) { usub = h; j2 = j; }
                    else { usub = umin; umin = h; j2 = j1; j1 = j; }
                }
            }
            if (j1 < 0) return 3;
            int i0 = y[j1];
            if (umin < usub) v[j1] -= (usub - umin);
            else if (i0 >= 0 && j2 >= 0) { j1 = j2; i0 = y[j1]; }
            x[i] = j1; y[j1] = i;
            if (i0 >= 0) {
                x[i0] = -1;
                if (umin < usub) free_rows[nfree++] = i0;
                else free_rows[prv++] = i0;
            }
        }
    }

    std::fill(x.begin(), x.end(), -1);
    for (int j = 0; j < N; ++j) if (y[j] >= 0) x[y[j]] = j;
    nfree = 0;
    for (int i = 0; i < N; ++i) if (x[i] < 0) free_rows[nfree++] = i;
    auto T1 = clk::now();

    // Fibonacci-free: use a binary heap with decrease-key via handles
    std::vector<int> heap;
    std::vector<int> hpos(N, -1);
    heap.reserve(4096);
    auto hswap = [&](int a, int b) {
        int ja = heap[a], jb = heap[b];
        heap[a] = jb; heap[b] = ja;
        hpos[ja] = b; hpos[jb] = a;
    };
    auto hup = [&](int p) {
        while (p > 0) {
            int parent = (p - 1) >> 1;
            if (d[heap[p]] < d[heap[parent]]) { hswap(p, parent); p = parent; }
            else break;
        }
    };
    auto hdown = [&](int p) {
        int sz = (int)heap.size();
        while (true) {
            int l = p * 2 + 1, r = l + 1, best = p;
            if (l < sz && d[heap[l]] < d[heap[best]]) best = l;
            if (r < sz && d[heap[r]] < d[heap[best]]) best = r;
            if (best == p) break;
            hswap(p, best); p = best;
        }
    };

    std::vector<int> seen(N, 0);
    int stamp = 0;
    std::vector<int> scanned;
    scanned.reserve(256);

    for (int f = 0; f < nfree; ++f) {
        int freerow = free_rows[f];
        if (++stamp == 0) { std::fill(seen.begin(), seen.end(), 0); stamp = 1; }
        heap.clear();
        scanned.clear();
        for (int p = row_ptr[freerow]; p < row_ptr[freerow + 1]; ++p) {
            int j = col_idx[p];
            d[j] = C(freerow, j) - v[j];
            pred[j] = freerow;
            seen[j] = stamp;
            hpos[j] = (int)heap.size();
            heap.push_back(j);
        }
        for (int p = ((int)heap.size() - 2) / 2; p >= 0; --p) hdown(p);

        int endofpath = -1;
        while (!heap.empty()) {
            int j = heap[0];
            double mind = d[j];
            // pop
            int last = heap.back(); heap.pop_back();
            hpos[j] = -2; // scanned marker
            if (!heap.empty()) { heap[0] = last; hpos[last] = 0; hdown(0); }
            if (y[j] < 0) { endofpath = j; break; }
            scanned.push_back(j);
            int i = y[j];
            double base = mind - (C(i, j) - v[j]);
            for (int p = row_ptr[i]; p < row_ptr[i + 1]; ++p) {
                int j2 = col_idx[p];
                if (hpos[j2] == -2 && seen[j2] == stamp) continue; // already scanned
                double nd = base + C(i, j2) - v[j2];
                if (seen[j2] != stamp) {
                    d[j2] = nd;
                    pred[j2] = i;
                    seen[j2] = stamp;
                    hpos[j2] = (int)heap.size();
                    heap.push_back(j2);
                    hup(hpos[j2]);
                } else if (hpos[j2] >= 0 && nd < d[j2]) {
                    d[j2] = nd;
                    pred[j2] = i;
                    hup(hpos[j2]);
                }
            }
        }
        if (endofpath < 0) return 4;
        double mind = d[endofpath];
        for (int j : scanned) v[j] += d[j] - mind;
        // reset hpos of remaining heap nodes
        for (int j : heap) hpos[j] = -1;
        int j = endofpath;
        while (true) {
            int i = pred[j];
            y[j] = i;
            int jnext = x[i];
            x[i] = j;
            j = jnext;
            if (i == freerow) break;
        }
    }
    auto T2 = clk::now();
    auto ms = [](auto a, auto b){ return std::chrono::duration<double,std::milli>(b-a).count(); };
    std::fprintf(stderr, "augs %d init %.2f aug %.2f total %.2f nnz %d\n",
                 nfree, ms(T0,T1), ms(T1,T2), ms(T0,T2), nnz);
    for (int i = 0; i < N; ++i) rowsol[i] = x[i];
    return 0;
}
