#include <vector>
#include <cstdint>
#include <algorithm>
#include <cstring>
#include <cmath>

// Sparse forward auction. Candidates: entries <= thr, plus Kmin nearest if fewer.
// Gauss-Seidel, epsilon scaling. Returns 0 and a column assignment per row.
extern "C" int auction_solve(int n, const double* cost, int* rowsol) {
    const int N = n;
    const double THR = 0.40;
    const int KMIN = 64;
    const double EPS_FINAL = 1e-7;
    const double EPS_FACTOR = 0.2;

    std::vector<int> row_ptr(N + 1);
    std::vector<int> cols;
    cols.reserve((size_t)N * 100);
    std::vector<int> tmp(N);
    std::vector<char> in(N);
    row_ptr[0] = 0;
    for (int i = 0; i < N; ++i) {
        const double* row = cost + (size_t)i * N;
        for (int j = 0; j < N; ++j) if (row[j] <= THR) cols.push_back(j);
        int cnt = (int)cols.size() - row_ptr[i];
        if (cnt < KMIN) {
            for (int j = 0; j < N; ++j) tmp[j] = j;
            std::nth_element(tmp.begin(), tmp.begin() + KMIN, tmp.end(),
                             [&](int a, int b) { return row[a] < row[b]; });
            std::fill(in.begin(), in.end(), 0);
            for (int p = row_ptr[i]; p < (int)cols.size(); ++p) in[cols[p]] = 1;
            for (int k = 0; k < KMIN; ++k) if (!in[tmp[k]]) cols.push_back(tmp[k]);
        }
        row_ptr[i + 1] = (int)cols.size();
    }

    std::vector<double> price(N, 0.0);
    std::vector<int> owner(N, -1), free_list(N);
    double eps = THR * 0.25;

    for (int round = 0; round < 30; ++round) {
        std::fill(owner.begin(), owner.end(), -1);
        int nfree = N;
        for (int i = 0; i < N; ++i) free_list[i] = i;
        long long bids = 0;
        const long long BID_MAX = (long long)N * 600;
        while (nfree > 0 && bids < BID_MAX) {
            ++bids;
            int i = free_list[--nfree];
            const double* row = cost + (size_t)i * N;
            double v1 = -1e300, v2 = -1e300;
            int j1 = -1;
            for (int p = row_ptr[i]; p < row_ptr[i + 1]; ++p) {
                int j = cols[p];
                double val = -row[j] - price[j];
                if (val > v1) { v2 = v1; v1 = val; j1 = j; }
                else if (val > v2) v2 = val;
            }
            if (j1 < 0) return 3;
            if (v2 < -1e200) v2 = v1 - 1.0;
            price[j1] += (v1 - v2) + eps;
            int prev = owner[j1];
            owner[j1] = i;
            if (prev >= 0) free_list[nfree++] = prev;
        }
        if (nfree == 0 && eps <= EPS_FINAL) {
            for (int j = 0; j < N; ++j) {
                int i = owner[j];
                if (i < 0) return 5;
                rowsol[i] = j;
            }
            return 0;
        }
        if (nfree > 0) {
            eps *= EPS_FACTOR;
            if (eps < EPS_FINAL * 0.5) return 1;
            continue;
        }
        eps *= EPS_FACTOR;
        if (eps < EPS_FINAL) eps = EPS_FINAL;
    }
    return 2;
}
