import ctypes
import numpy as np
from pathlib import Path

_lib = ctypes.CDLL(str(Path(__file__).resolve().with_name("libauction.so")))
_lib.auction_solve.argtypes = [ctypes.c_int, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_int)]
_lib.auction_solve.restype = ctypes.c_int


class Solver:
    def solve(self, problem, **kwargs):
        a = np.asarray(problem["source_weights"], dtype=np.float64)
        M = np.ascontiguousarray(problem["cost_matrix"], dtype=np.float64)
        n = int(M.shape[0])
        rowsol = np.empty(n, dtype=np.int32)
        rc = _lib.auction_solve(
            n,
            M.ctypes.data_as(ctypes.POINTER(ctypes.c_double)),
            rowsol.ctypes.data_as(ctypes.POINTER(ctypes.c_int)),
        )
        if rc != 0:
            import ot
            b = np.asarray(problem["target_weights"], dtype=np.float64)
            return {"transport_plan": ot.lp.emd(a, b, M, check_marginals=False)}
        G = np.zeros((n, n), dtype=np.float64)
        G[np.arange(n), rowsol] = a
        return {"transport_plan": G}
